const r2 = v => Math.round(v * 100) / 100;
// Catmull-Rom through points, as cubic segments (the first point is the current point).
function crSide(pts) {
  let d = '';
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(i - 1, 0)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(i + 2, pts.length - 1)];
    d += `C${r2(p1[0] + (p2[0] - p0[0]) / 6)} ${r2(p1[1] + (p2[1] - p0[1]) / 6)} ${r2(p2[0] - (p3[0] - p1[0]) / 6)} ${r2(p2[1] - (p3[1] - p1[1]) / 6)} ${r2(p2[0])} ${r2(p2[1])}`;
  }
  return d;
}
// prof: [[y, halfWidth], ...] top to bottom; returns a closed outline symmetric about x=100.
function outline(prof) {
  const R = prof.map(([y, h]) => [100 + h, y]);
  const L = prof.slice().reverse().map(([y, h]) => [100 - h, y]);
  return `M${r2(R[0][0])} ${r2(R[0][1])}${crSide(R)}L${r2(L[0][0])} ${r2(L[0][1])}${crSide(L)}Z`;
}
function hwAt(prof, y) {
  for (let i = 0; i < prof.length - 1; i++) {
    const [y0, h0] = prof[i], [y1, h1] = prof[i + 1];
    if (y >= y0 && y <= y1) return h0 + (h1 - h0) * (y - y0) / (y1 - y0 || 1);
  }
  return prof[prof.length - 1][1];
}
// A molded horizontal rib following the bottle's curvature: dark groove with a light lip below.
const rib = (prof, y, sag = 3, dark = '#7f98a6', o = .5) => {
  const h = hwAt(prof, y) - .4;
  return `<path d="M${r2(100 - h)} ${y}Q100 ${r2(y + sag)} ${r2(100 + h)} ${y}" fill="none" stroke="${dark}" stroke-opacity="${o}" stroke-width="1.1"/><path d="M${r2(100 - h)} ${r2(y + 1.3)}Q100 ${r2(y + sag + 1.3)} ${r2(100 + h)} ${r2(y + 1.3)}" fill="none" stroke="#fff" stroke-opacity=".75" stroke-width=".9"/>`;
};
// Petaloid feet: valleys between five feet seen from the front.
function feet(prof, yTop = 216, col = '#8fa9b6') {
  const yb = prof[prof.length - 1][0], h = hwAt(prof, yTop + 6);
  return [-.6, .6].map(s => {
    const x = 100 + s * h;
    return `<path d="M${r2(x - 5.5)} ${yb}Q${r2(x - 4.5)} ${yTop} ${r2(x)} ${yTop}Q${r2(x + 4.5)} ${yTop} ${r2(x + 5.5)} ${yb}" fill="#fff" fill-opacity=".5" stroke="${col}" stroke-opacity=".75" stroke-width=".9"/><path d="M${r2(x - 2.2)} ${r2(yb - 1)}Q${r2(x - 1.6)} ${yTop + 4} ${r2(x)} ${yTop + 3.6}" fill="none" stroke="#fff" stroke-opacity=".8" stroke-width="1.1"/>`;
  }).join('') + [-1, 1].map(s => `<path d="M${r2(100 + s * (h - 1))} ${r2(yTop + 2)}Q${r2(100 + s * (h - 4))} ${r2(yb - 6)} ${r2(100 + s * (h - 7.5))} ${yb}" fill="none" stroke="${col}" stroke-opacity=".6" stroke-width=".9"/>`).join('') + `<path d="M${r2(100 - h + 9)} ${r2(yb - .6)}Q100 ${r2(yb + 1.4)} ${r2(100 + h - 9)} ${r2(yb - .6)}" fill="none" stroke="${col}" stroke-opacity=".5"/>`;
}
// Low petaloid base: shallow lobes and a bright bottom edge.
function lowBase(prof) {
  const yb = prof[prof.length - 1][0], h = hwAt(prof, yb - 8);
  const lobes = [-.62, 0, .62].map(f => {
    const x = 100 + f * h, w = f ? 7 : 9;
    return `<path d="M${r2(x - w)} ${r2(yb - .4)}Q${r2(x)} ${r2(yb - 8.5)} ${r2(x + w)} ${r2(yb - .4)}" fill="none" stroke="#8fa2ad" stroke-opacity=".45" stroke-width=".9"/><path d="M${r2(x - w + 2)} ${r2(yb - 1.4)}Q${r2(x)} ${r2(yb - 6.8)} ${r2(x + w - 2)} ${r2(yb - 1.4)}" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width=".8"/>`;
  }).join('');
  return `<path d="M${r2(100 - h)} ${r2(yb - 9)}Q100 ${r2(yb - 6)} ${r2(100 + h)} ${r2(yb - 9)}V${yb}H${r2(100 - h)}Z" fill="${ref('baseg')}" clip-path="${ref('b')}"/>` + lobes +
    `<path d="M${r2(100 - h + 4)} ${r2(yb - .9)}Q100 ${r2(yb + .6)} ${r2(100 + h - 4)} ${r2(yb - .9)}" fill="none" stroke="#fff" stroke-opacity=".95" stroke-width="1.3"/>`;
}
// Clear PET body: deeper edges, lighter center (horizontal), plus a light liquid tint below the water line.
const petDefs = (liq = true) => `<linearGradient id="__ID__pet"><stop stop-color="#93a2ab" stop-opacity=".88"/><stop offset=".07" stop-color="#bcc8cf" stop-opacity=".86"/><stop offset=".18" stop-color="#e6ecef" stop-opacity=".86"/><stop offset=".26" stop-color="#f6f8fa" stop-opacity=".86"/><stop offset=".5" stop-color="#fcfdfd" stop-opacity=".86"/><stop offset=".72" stop-color="#f4f7f9" stop-opacity=".86"/><stop offset=".84" stop-color="#dde5ea" stop-opacity=".87"/><stop offset=".94" stop-color="#b4c1c9" stop-opacity=".88"/><stop offset="1" stop-color="#909fa9" stop-opacity=".9"/></linearGradient>` + (liq ? `<linearGradient id="__ID__liq" x2="0" y2="1"><stop stop-color="#d7e6ee" stop-opacity=".05"/><stop offset="1" stop-color="#b3cad6" stop-opacity=".2"/></linearGradient>` : '');
const highlights = (prof, y0, y1, o = .7) => {
  const pts = l => [y0, (y0 + y1) / 2, y1].map(y => [r2(100 - hwAt(prof, y) * l), y]);
  const a = pts(.7), b = [y0 + 6, y1 - 4].map(y => [r2(100 + hwAt(prof, y) * .8), y]);
  return `<path d="M${a[0][0]} ${a[0][1]}Q${r2(a[1][0] - 1)} ${a[1][1]} ${a[2][0]} ${a[2][1]}" fill="none" stroke="#fff" stroke-opacity="${o}" stroke-width="4.2" stroke-linecap="round"/><path d="M${b[0][0]} ${b[0][1]}L${b[1][0]} ${b[1][1]}" stroke="#fff" stroke-opacity="${r2(o * .45)}" stroke-width="1.8" stroke-linecap="round"/>`;
};
const waterLine = (prof, y) => {
  const h = hwAt(prof, y) - .6;
  return `<rect x="40" y="${y}" width="120" height="${r2(236 - y)}" fill="${ref('liq')}"/><ellipse cx="100" cy="${y}" rx="${r2(h)}" ry="1.8" fill="#fff" fill-opacity=".35" stroke="#9cb9c7" stroke-opacity=".6" stroke-width=".7"/>`;
};
const clipDef = (id, d) => `<clipPath id="__ID__${id}"><path d="${d}"/></clipPath>`;

